337	// Which lifecycle actions an invoice offers depends on where it is in its lifecycle: a draft can be
338	// sent, a sent invoice can be marked paid. Collecting the mapping here keeps the row markup flat and
339	// gives one obvious place to add a new lifecycle action.
340	function InvoiceActions({
341	  invoice,
342	  onOpen,
343	  onSend,
344	  onPay,
345	  onCancel,
346	}: {
347	  invoice: Invoice;
348	  onOpen: () => void;
349	  onSend: () => void;
350	  onPay: () => void;
351	  onCancel: () => void;
352	}) {
353	  return (
354	    <>
355	      <button data-testid={`invoice-open-${invoice.id}`} onClick={onOpen}>
356	        Open
357	      </button>
358	      {invoice.status === 'DRAFT' && (
359	        <button data-testid={`invoice-send-${invoice.id}`} onClick={onSend}>
360	          Send
361	        </button>
362	      )}
363	      {invoice.status === 'SENT' && (
364	        <button data-testid={`invoice-pay-${invoice.id}`} onClick={onPay}>
365	          Mark paid
366	        </button>
367	      )}
368	      {invoice.status === 'SENT' && (
369	        <button data-testid={`invoice-cancel-${invoice.id}`} onClick={onCancel}>
370	          Cancel
371	        </button>
372	      )}
373	    </>
374	  );
375	}
