494	// A project's budget: what was set for it, what has been invoiced against it so far, and what is
495	// left over. Invoiced (and so remaining) is derived from the project's invoices, so the owner bumps
496	// `reloadKey` whenever they change and this re-reads the budget picture. Owns its own budget state.
497	function BudgetPanel({ projectId, reloadKey }: { projectId: number; reloadKey: number }) {
498	  const [budget, setBudget] = useState<ProjectBudget | null>(null);
499	  const [budgetInput, setBudgetInput] = useState('');
500	
501	  async function load() {
502	    const res = await fetch(`/api/projects/${projectId}/budget`);
503	    setBudget(await res.json());
504	  }
505	
506	  useEffect(() => {
507	    void load();
508	  }, [projectId, reloadKey]);
509	
510	  async function submit(e: React.FormEvent) {
511	    e.preventDefault();
