517	      method: 'POST',
518	      headers: { 'Content-Type': 'application/json' },
519	      body: JSON.stringify({ budget: value }),
520	    });
521	    setBudgetInput('');
522	    await load();
523	  }
524	
525	  return (
526	    <section data-testid="project-budget-panel">
527	      <p data-testid="project-budget">
528	        {budget && budget.budget != null ? moneyGrouped(budget.budget) : ''}
529	      </p>
530	      <p data-testid="project-invoiced">{moneyGrouped(budget ? budget.invoiced : 0)}</p>
531	      <p data-testid="project-remaining">
532	        {budget && budget.remaining != null ? moneyGrouped(budget.remaining) : ''}
533	      </p>
534	      <form data-testid="project-budget-form" onSubmit={submit}>
535	        <input
536	          data-testid="project-budget-input"
537	          placeholder="Budget"
538	          value={budgetInput}
539	          onChange={(e) => setBudgetInput(e.target.value)}
540	        />
541	        <button data-testid="project-budget-submit" type="submit">
542	          Set budget
543	        </button>
544	      </form>
545	    </section>
546	  );
547	}
