604	            .filter((t) => !tags.some((mine) => mine.id === t.id))
605	            .map((t) => (
606	              <option key={t.id} value={String(t.id)}>
607	                {t.name}
608	              </option>
609	            ))}
610	        </select>
611	        <button data-testid="project-tag-add-submit" type="submit">
612	          Add label
613	        </button>
614	      </form>
615	    </>
616	  );
617	}
