665	// A project's notes: a running list of what has been jotted against it and a form to add another.
666	// Owns its own note state, scoped to the one project.
667	function NotesPanel({ projectId }: { projectId: number }) {
668	  const [notes, reload] = useJsonResource<Note[]>(
669	    `/api/notes?targetType=project&targetId=${projectId}`,
670	    [],
671	  );
672	  const [noteText, setNoteText] = useState('');
